import{_ as s,m as a,k as i,ah as t}from"./chunks/framework.HEc25T99.js";const u=JSON.parse('{"title":"Updating Creopse","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"developers/development/updating-creopse.md","filePath":"src/en/developers/development/updating-creopse.md"}'),n={name:"developers/development/updating-creopse.md"};function o(p,e,l,r,h,d){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="updating-creopse" tabindex="-1">Updating Creopse <a class="header-anchor" href="#updating-creopse" aria-label="Permalink to &quot;Updating Creopse&quot;">​</a></h1><p>The <code>creopse/creopse</code> package is versioned through Git tags (currently the <code>v0.x</code> series — the API may still evolve) and updates like any other Composer dependency, with one particularity: the files published into the host application at install time don&#39;t update themselves.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>There is no published changelog yet, nor a dedicated <code>creopse:update</code> command — updating goes through a controlled reinstall (<code>creopse:install</code>) rather than an automated migration path.</p></div><h2 id="_1-update-the-package" tabindex="-1">1. Update the package <a class="header-anchor" href="#_1-update-the-package" aria-label="Permalink to &quot;1. Update the package&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> creopse/creopse</span></span></code></pre></div><h2 id="_2-back-up-your-customized-files" tabindex="-1">2. Back up your customized files <a class="header-anchor" href="#_2-back-up-your-customized-files" aria-label="Permalink to &quot;2. Back up your customized files&quot;">​</a></h2><p><code>php artisan creopse:install</code> republishes the package&#39;s entire file set into the host application, overwriting by default (force mode):</p><ul><li><code>tailwind.config.js</code>, <code>postcss.config.js</code>, <code>vite.config.js</code></li><li><code>routes/api.php</code>, <code>routes/web.php</code></li><li>the entire <code>resources/</code> directory</li><li>files under <code>database/migrations</code> and <code>database/seeders</code></li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Any custom change in these locations must be committed, backed up, or stashed before rerunning the command — otherwise it&#39;s lost. The <code>--no-force</code> option disables this behavior if needed.</p></div><h2 id="_3-rerun-the-installer" tabindex="-1">3. Rerun the installer <a class="header-anchor" href="#_3-rerun-the-installer" aria-label="Permalink to &quot;3. Rerun the installer&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> creopse:install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vue</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # or -t react, depending on the project&#39;s frontend</span></span></code></pre></div><p>This is the step that actually republishes the newly installed version&#39;s files (admin interface configuration and assets, frontend resources, routes, controllers, models, enums...) — <code>composer update</code> alone isn&#39;t enough.</p><h2 id="_4-run-migrations" tabindex="-1">4. Run migrations <a class="header-anchor" href="#_4-run-migrations" aria-label="Permalink to &quot;4. Run migrations&quot;">​</a></h2><p><code>creopse:install</code> does <strong>not</strong> run migrations or seeders automatically. Once the new files have been republished:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span></span></code></pre></div><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> creopse/creopse</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># back up any change under resources/, routes/api.php, routes/web.php,</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># database/migrations, database/seeders if needed</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> creopse:install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vue</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span></span></code></pre></div><p>See also <a href="./../deployment/production.html">Production Deployment</a> for the checklist to revalidate after an update.</p>`,18)])])}const k=s(n,[["render",o]]);export{u as __pageData,k as default};
